package dev.eugheist.ttmodern;
final class ProtoclayWorldClientAudit {
 static volatile boolean checked;static java.util.List<net.minecraft.world.item.ItemStack> inventory;static int selected;static net.minecraft.world.phys.Vec3 position;static float yaw,pitch;static boolean mayfly,flying;static final java.util.Map<net.minecraft.core.BlockPos,net.minecraft.world.level.block.state.BlockState> blocks=new java.util.HashMap<>();static final net.minecraft.core.BlockPos TARGET=new net.minecraft.core.BlockPos(5,290,5);
 static void restore(net.minecraft.client.Minecraft mc){if(inventory==null)return;var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());p.getInventory().clearContent();for(int i=0;i<inventory.size();i++)p.getInventory().setItem(i,inventory.get(i));p.getInventory().selected=selected;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(selected));p.getAbilities().mayfly=mayfly;p.getAbilities().flying=flying;p.onUpdateAbilities();blocks.forEach((pos,state)->p.level().setBlock(pos,state,3));p.connection.teleport(position.x,position.y,position.z,yaw,pitch);p.inventoryMenu.broadcastChanges();inventory=null;}
 static void tick(net.minecraft.client.Minecraft mc,int tick){try{step(mc,tick);}catch(RuntimeException e){mc.getSingleplayerServer().submit(()->restore(mc)).join();throw e;}}
 static void step(net.minecraft.client.Minecraft mc,int tick){
  if(tick==880)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());var inv=p.getInventory();inventory=new java.util.ArrayList<>();for(int i=0;i<inv.getContainerSize();i++)inventory.add(inv.getItem(i).copy());selected=inv.selected;position=p.position();yaw=p.getYRot();pitch=p.getXRot();mayfly=p.getAbilities().mayfly;flying=p.getAbilities().flying;inv.clearContent();inv.selected=0;p.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));inv.setItem(0,new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get()));inv.setItem(5,new net.minecraft.world.item.ItemStack(Protoclay.ITEM.get()));var shovel=new net.minecraft.world.item.ItemStack(AwakenedShovel.ITEM.get());AdvancedToolModes.change(shovel);inv.setItem(7,shovel);for(int y=0;y<5;y++){var pos=TARGET.above(y);blocks.put(pos,p.level().getBlockState(pos));p.level().setBlock(pos,(y==0?net.minecraft.world.level.block.Blocks.SNOW_BLOCK:net.minecraft.world.level.block.Blocks.AIR).defaultBlockState(),3);}p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(5.5,292,5.5,0,90);p.inventoryMenu.broadcastChanges();});
  if(tick==890){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedPick.ITEM.get())&&mc.player.getInventory().getItem(5).is(Protoclay.ITEM.get()),"native protoclay inventory fixture sync");mc.player.swing(net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(tick==900){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedShovel.ITEM.get())&&AdvancedToolModes.get(mc.player.getMainHandItem())==1&&mc.player.getInventory().getItem(7).is(AwakenedPick.ITEM.get()),"natural client/server swing switches snow to shovel with mode preserved");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(p.getMainHandItem().is(AwakenedShovel.ITEM.get()),"native server inventory tick switched to shovel");p.level().setBlock(TARGET,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);});}
  if(tick==910)mc.player.swing(net.minecraft.world.InteractionHand.MAIN_HAND);
  if(tick==920){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedPick.ITEM.get())&&mc.player.getInventory().getItem(7).is(AwakenedShovel.ITEM.get())&&AdvancedToolModes.get(mc.player.getInventory().getItem(7))==1,"second natural swing swaps back without item/mode loss");mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());try{EnchanterClientAudit.check(p.getMainHandItem().is(AwakenedPick.ITEM.get())&&p.getInventory().getItem(5).getCount()==1,"server agrees and protoclay not consumed");checked=true;System.out.println("TT PROTOCLAY WORLD CLIENT AUDIT: ALL PASS (natural player inventory ticks,real swing packets,snow/stone bidirectional selection,client/server slot sync,mode retained,no consumption,restored fixture)");}finally{restore(mc);}});}
 }
}
